/**
 * E.2 A/B LLM eval for Go/Rust/Java import resolution (2.37-2.39).
 *
 * Compares agent task performance using context generated by:
 * - main (no import resolution) -> /tmp/clarte-eval-import-res/{lang}-baseline.md
 * - branch (resolved imports) -> /tmp/clarte-eval-import-res/{lang}-experiment.md
 *
 * Pre-generation:
 *   See generation steps in the experimental branch README or run the
 *   baseline/experiment generation scripts before this test.
 *
 * Skipped unless LLM_EVAL=1 and ANTHROPIC_API_KEY are set.
 *
 * Run:  LLM_EVAL=1 npx vitest run src/__tests__/eval/import-resolution-eval.test.ts
 */

import { describe, it, expect, beforeAll } from "vitest";
import Anthropic from "@anthropic-ai/sdk";
import { readFileSync, existsSync } from "node:fs";

const SKIP = !process.env.LLM_EVAL || !process.env.ANTHROPIC_API_KEY;
const N_ITERS = parseInt(process.env.N_ITERS ?? "1", 10);
const MODEL = "claude-sonnet-4-6";
const TEMPERATURE = parseFloat(process.env.EVAL_TEMP ?? "0");

const COST_PER_M_INPUT = 3.0;
const COST_PER_M_OUTPUT = 15.0;

// ── Tasks per language ──────────────────────────────────────────────────────

interface EvalTask {
  id: string;
  category: string;
  question: string;
  judgePrompt: string;
}

interface LanguageEval {
  lang: string;
  baselinePath: string;
  experimentPath: string;
  tasks: EvalTask[];
}

